/**
 * Seeds generic_documents with claim form documents (path: documents/claims_forms/).
 * Uses GenericDocument model with all values set per row.
 */
class ClaimFormsGenericDocumentSeeder extends Seeder
{
    private const DOCUMENTABLE_TYPE = Claim::class;
    private const DOCUMENTABLE_ID = 1;
    private const CREATED_BY_ID = 1030;
    private const MIME_TYPE = 'application/pdf';
    private const PATH_PREFIX = 'documents/claims_forms/';

    /**
     * Run the database seeds.
     */
    public function run(): void
    {
        $rows = $this->getRows();

        $providers = InsuranceProvider::select('id', 'code')->withActive()->orderBy('id')->get();

        DB::transaction(function () use ($rows, $providers): void {
            foreach ($rows as $row) {
                $provider = $providers->firstWhere('code', $row['insurance_provider_code']);

                if (! $provider) {
                    LoggerService::warning('ClaimFormsGenericDocumentSeeder: skipping document, provider inactive or not found', extra: [
                        'document' => $row['name'],
                        'insurance_provider_code' => $row['insurance_provider_code'],
                    ]);

                    continue;
                }

                GenericDocument::updateOrCreate(
                    ['uuid' => $row['uuid']],
                    [
                        'generic_document_type_id' => $row['generic_document_type_id'],
                        'documentable_type' => self::DOCUMENTABLE_TYPE,
                        'documentable_id' => self::DOCUMENTABLE_ID,
                        'quote_type_id' => $row['quote_type_id'],
                        'name' => $row['name'],
                        'path' => $row['path'],
                        'mime_type' => self::MIME_TYPE,
                        'created_by_id' => self::CREATED_BY_ID,
                        'insurance_provider_id' => $provider->id,
                        'business_type_of_insurance_id' => $row['business_type_of_insurance_id'],
                        'created_at' => $row['created_at'],
                        'updated_at' => $row['updated_at'],
                    ]
                );
            }
        });
    }

